python3 - <<'PY'
import re,glob,os
tab={}
for line in open('draft/numerals.md'):
    m=re.match(r'\|\s*(\d+)\s*\|\s*(.+?)\s*\|$',line.strip())
    if m: tab[m.group(1)]=m.group(2)
print("table",len(tab))
for f in sorted(glob.glob('figures/*.md')):
    txt=open(f).read()
    body,_,lst=txt.partition('## Numerals shown on this figure')
    listed=set(re.findall(r'^- (\d+):',lst,re.M))
    used=set(re.findall(r'\b(\d{2})\b',body))
    used={u for u in used if u in tab}
    print(os.path.basename(f), 'listed',len(listed), 'chars',len(txt),
          'in body not listed',used-listed, 'listed not in body',listed-used,
          'not in table',listed-set(tab))
alltext=''.join(open(p).read() for p in glob.glob('draft/*.md'))
for bad in ['—','TODO','TBD','[ ]','placeholder','XXX']:
    if bad in alltext or any(bad in open(p).read() for p in glob.glob('figures/*.md')):
        print('MARKER',bad)
